tape( 'the function performs the matrix-matrix operation `C = α*A*B + β*C` (column_major, column_major, column_major, left, lower)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var b;
	var c;

	data = cacbccll;

	a = new Float32Array( data.A );
	b = new Float32Array( data.B );
	c = new Float32Array( data.C );

	expected = new Float32Array( data.C_out );

	out = ssymm( data.side, data.uplo, data.M, data.N, data.alpha, a, data.strideA1, data.strideA2, data.offsetA, b, data.strideB1, data.strideB2, data.offsetB, data.beta, c, data.strideC1, data.strideC2, data.offsetC );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

